(()=>{const images=window.ATLAS_ILLUSTRATION_DATA?.images;if(!images)return;for(const [id,link] of Object.entries({"lisa-4fda33add96dcd":{"item":27,"objective":"27-14","pathway":"gyn-27-hsv-initial","decision":true,"note":"Figure CNGOF 2017 reprise dans LiSA. Les branches initiale primaire/non primaire et récurrence sont conservées. La rupture avant terme nécessite une décision multidisciplinaire intégrant la prématurité ; l’arbre principal de la figure concerne la rupture à terme. Les traitements détaillés relèvent du protocole spécialisé."},"lisa-c7201d62403c3f":{"item":27,"objective":"27-14","pathway":"gyn-27-hsv-recurrence","decision":true,"note":"Les deux branches pendant grossesse et pendant travail sont conservées. La figure simplifie la voie d’accouchement : la RPC parle de situations favorisant une option, sans imposer une césarienne pour toute récurrence. La rupture prématurée avant 37 SA relève d’une discussion spécifique."},"lisa-9ec50ca2be44d8":{"item":36,"objective":"36-14","pathway":"gyn-36-oubli","decision":true,"note":"Le schéma source utilise les seuils de 12 h (COP/désogestrel) et 3 h (lévonorgestrel). Il ne couvre pas toutes les pilules, notamment la drospirénone 24 h. La branche ulipristal et son délai de reprise de 5 jours sont des compléments actualisés. Consulter la notice du produit pour les règles exactes ; la reprise immédiate du schéma historique n’est pas universelle."},"lisa-020b30ce6608fe":{"item":40,"objective":"40-8","pathway":"gyn-40-chronique","decision":true,"note":"Les branches cyclique/non cyclique, génitale/extra-génitale et organique/fonctionnelle sont conservées. La formulation « psychogène » de l’image est contextualisée : une douleur persistante nécessite une évaluation globale, sans diagnostic d’exclusion psychologique automatique."},"lisa-6d7ef154190f93":{"item":42,"objective":"42-3","pathway":"gyn-42-hormones","decision":true,"note":"Trois profils hormonaux et branche prolactine de la figure conservés. La grossesse est exclue en préalable ; dosages et échographie restent interprétés avec le contexte. La cause ovarienne n’est dite prématurée que selon l’âge."},"lisa-a42f5addb5d8a9":{"item":42,"objective":"42-3","pathway":"gyn-42-progestatif","decision":true,"note":"Branches positif/négatif, anatomique/hypoestrogénie et centrale/ovarienne conservées. Le schéma source mentionne dydrogestérone 10–20 mg/j pendant 7–10 jours : protocole médical, pas prescription automatique. Un test ne prouve ni n’exclut à lui seul chaque étiologie."},"lisa-0bb9d620ea6d89":{"item":124,"objective":"124-9","pathway":"gyn-124-thm","decision":true,"note":"L’image illustre quatre calendriers : combiné ou séquentiel, avec estrogènes continus ou discontinus. Ces options sont distinguées dans le parcours. La vérification de l’indication, des contre-indications et de l’utérus constitue un complément préalable. Le nombre de jours dépend du produit prescrit."},"lisa-0bd05ad435e2d1":{"item":300,"objective":"300-5","pathway":"gyn-300-hpv","decision":true,"note":"Toutes les branches HPV initial, cytologie réflexe et contrôle à un an sont transcrites. Le parcours s’arrête à la colposcopie ; les suites dépendent de l’histologie. Les situations particulières relèvent des recommandations dédiées/actualisées."},"lisa-9613967ee2f200":{"item":300,"objective":"300-14","pathway":"gyn-300-endometre","decision":true,"note":"Branches endomètre fin, épaissi, biopsie positive/négative et reprise des saignements conservées. Le seuil frontière de 4 mm est explicité. Le terme « élimination » du schéma est remplacé par surveillance avec consignes ; une récidive exige réévaluation. L’IRM et le bilan distant sont guidés par le risque, puis discussion en RCP."},"lisa-77191d1e24f61b":{"item":312,"objective":"312-9","pathway":"gyn-312-birads","decision":true,"note":"Le tableau décisionnel est transposé par catégories 0 à 6. La ligne 6 de l’image indique chirurgie : le parcours précise RCP et traitements adaptés, car une stratégie néoadjuvante est parfois indiquée."},"lisa-ec0057320fac79":{"item":344,"objective":"344-8","pathway":"gyn-344-preeclampsie","decision":true,"note":"Diagnostic, bilan, évaluation de gravité, stabilisation, naissance et post-partum du schéma sont retranscrits. La protéinurie > 3 g/24 h de la figure historique ne suffit plus à définir la sévérité. Les seuils tensionnels utilisent « et/ou ». La naissance dépend du terme et de la gravité ; prééclampsie non sévère dès 37 SA : naissance recommandée. Magnésium et antihypertenseurs selon indication/protocole."},"lisa-083f59a2af4dc7":{"item":124,"objective":"124-11","pathway":"gyn-124-thm","decision":false,"note":"Tableau de contre-indications du THM ; consulter aussi le parcours THM et ses précautions."},"lisa-3c3e9570bc1fb4":{"item":43,"objective":"43-7","pathway":null,"decision":false,"note":"Classification anatomique FIGO des myomes, sans branche décisionnelle."},"lisa-62601385aaaea1":{"item":312,"objective":"312-7","pathway":null,"decision":false,"note":"Photographie clinique de rétraction mammaire."},"lisa-66e90d28689df8":{"item":124,"objective":"124-8","pathway":null,"decision":false,"note":"Chronologie descriptive des conséquences de la ménopause."},"lisa-68908da02983f9":{"item":124,"objective":"124-17","pathway":null,"decision":false,"note":"Classification descriptive des symptômes du déficit androgénique ; ne pose pas le diagnostic."},"lisa-6cc02a6f687a44":{"item":26,"objective":"26-4","pathway":"gyn-26-douleur","decision":false,"note":"Tableau étiologique avec conduites générales, relié au parcours douleur abdominale ; une césarienne n’est pas systématique pour toutes les causes."},"lisa-7ef8707b17dd4e":{"item":124,"objective":"124-17","pathway":null,"decision":false,"note":"Classification descriptive des signes physiques du déficit androgénique."},"lisa-8f49f5307941be":{"item":43,"objective":"43-1","pathway":null,"decision":false,"note":"Grille de quantification du score de Higham, pas un algorithme."},"lisa-91bbd31b2007f1":{"item":312,"objective":"312-7","pathway":null,"decision":false,"note":"Photographie clinique d’anomalie inflammatoire mammaire."},"lisa-974b9bc168795b":{"item":124,"objective":"124-15","pathway":null,"decision":false,"note":"Classification descriptive des symptômes du déficit androgénique."},"lisa-e8a59587ef1fa8":{"item":42,"objective":"42-6","pathway":"gyn-42-hormones","decision":false,"note":"Tableau des étiologies de l’IOP ; le bilan actualisé est précisé dans le cours."}}))if(images[id]){images[id].interactivePathway=link;images[id].algorithm=link.decision;}})();
